// Titles, summaries, key points, and full article bodies are stored here once.
// The Writing pages and AI Q&A both read this approved public content.
export type WritingPost = {
  title: string;
  date: string;
  summary: string;
  bullets: string[];
  body: string;
  coverImage?: string;
  coverAlt?: string;
  coverCaption?: string;
  references?: { label: string; url: string }[];
};

